"use strict";
function calcularArgumentos(sumUno, sumDos) {
    return sumUno + sumDos;
}
let resultado = calcularArgumentos(1, 2);
console.log(resultado);
function saludarR(nom) {
    return `Hola ${nom}`;
}
console.log(saludarR('Jimena'));
function sumar1(x, y, z) {
    return x + y + z;
}
let resultadoSuma = sumar1(2, 5, 3);
console.log(resultadoSuma);
let valor = 100;
console.log(resultadoSuma + valor);
